@namespace ghidra.features.@base.memsearch.gui;





using docking.widgets.button;
using ghidra.app.util;
using ghidra.features.@base.memsearch.scan;
using ghidra.util;
using help;
using help;

/**
 * Internal panel of the memory search window that manages the controls for the scan feature. This
 * panel can be added or removed via a toolbar action. Not showing by default.
 */
public class MemoryScanControlPanel : JPanel {
	private Scanner selectedScanner = Scanner.NOT_EQUALS;
	private bool hasResults;
	private bool isBusy;
	private JButton scanButton;
	private JButton compareButton;

	MemoryScanControlPanel(MemorySearchProvider provider) : base()
    {

		setLayout(new BoxLayout(this, BoxLayout.LINE_AXIS));

		setBorder(BorderFactory.createEmptyBorder(5, 0, 5, 0));

		scanButton = new JButton("Scan Values");
		scanButton.setMnemonic('V');
		scanButton.setEnabled(false);
		scanButton.setToolTipText("Refreshes byte values of current results and eliminates " +
			"those that don't meet the selected change criteria");

		add(scanButton);
		
		add(Box.createHorizontalStrut(20));

		compareButton = new JButton("Compare to...");
		compareButton.setEnabled(false);
		compareButton.setToolTipText("Create a new search using a new program, " +
			"remapping the current results");

		add(compareButton);
		
		add(Box.createHorizontalStrut(20));
		add(buildButtonPanel());

		HelpService helpService = Help.getHelpService();
		helpService.registerHelp(this, new HelpLocation(HelpTopics.SEARCH, "Scan_Controls"));

		scanButton.addActionListener(e => provider.scan(selectedScanner));
		compareButton.addActionListener(e => provider.generateNewProvider(selectedScanner));
	}

	private JComponent buildButtonPanel() {
		JPanel panel = new JPanel(new FlowLayout(FlowLayout.LEADING));
		ButtonGroup buttonGroup = new ButtonGroup();
		foreach (Scanner scanner in Scanner.values()) {
			GRadioButton button = new GRadioButton(scanner.getName());
			buttonGroup.add(button);
			panel.add(button);
			button.setSelected(scanner == selectedScanner);
			button.addActionListener(e => selectedScanner = scanner);
			button.setToolTipText(scanner.getDescription());
		}
		return panel;
	}

	public void setSearchStatus(bool hasResults, bool isBusy) {
		this.hasResults = hasResults;
		this.isBusy = isBusy;
		updateScanButton();
		updateCompareButton();
	}

	private void updateScanButton() {
		scanButton.setEnabled(canScan());
	}

	private bool canScan() {
		return hasResults && !isBusy;
	}

	private void updateCompareButton() {
		compareButton.setEnabled(canScan());
	}

}
